/** GPU-only driver; the UI submits immutable geometry/camera snapshots. */
final class RobotGpuRenderer implements GLSurfaceView.Renderer {
 static boolean supportsVersion(int version){return version>=0x20000;}
 private static final String VERTEX="uniform mat4 uMvp; attribute vec3 aPosition; attribute vec3 aNormal; attribute vec4 aColor; varying vec3 vNormal; varying vec4 vColor; void main(){ gl_Position=uMvp*vec4(aPosition,1.0); vNormal=aNormal; vColor=aColor; }";
 private static final String FRAGMENT="precision mediump float; uniform vec3 uView; varying vec3 vNormal; varying vec4 vColor; void main(){ vec3 n=normalize(vNormal); vec3 keyDir=normalize(vec3(0.4,-0.6,1.0)); float key=abs(dot(n,keyDir)); float fill=abs(dot(n,normalize(vec3(-0.8,0.2,0.5)))); float light=min(1.0,0.55+0.35*key+0.10*fill); vec3 halfSum=keyDir+normalize(uView); vec3 halfDir=halfSum/max(length(halfSum),0.0001); float specular=0.12*pow(abs(dot(n,halfDir)),24.0); float sky=0.02*(0.3+0.7*abs(n.z)); gl_FragColor=vec4(clamp(vColor.rgb*light+vec3(specular+sky),0.0,1.0),vColor.a); }";
 private static final class State {final java.util.Map<String,double[]> poses;final RobotGpuMesh.Data data;final double yaw,pitch;final float zoom;final int background;State(RobotGpuMesh.Data d,double y,double p,float z,int b){this(d,y,p,z,b,null);}
 State(RobotGpuMesh.Data d,double y,double p,float z,int b,java.util.Map<String,double[]> t){poses=t;data=d;yaw=y;pitch=p;zoom=z;background=b;}}
 private volatile State pending=new State(null,.65,.4,1,0xff101720);
 private final BiConsumer<RobotGpuMesh.Data,String> failure;
 private final java.util.IdentityHashMap<RobotCad.Chunk,int[]> cadBuffers=new java.util.IdentityHashMap<>();private int cadProgram;
 private RobotGpuMesh.Data uploaded;private int program,vbo,position,normal,color,mvp,viewDirection,width=1,height=1;private boolean failed;
 RobotGpuRenderer(BiConsumer<RobotGpuMesh.Data,String> listener){failure=listener;}
 void scene(RobotGpuMesh.Data d,double yaw,double pitch,float zoom,int background){pending=new State(d,yaw,pitch,zoom,background);}
 void scene(RobotGpuMesh.Data d,double yaw,double pitch,float zoom,int background,java.util.Map<String,double[]> poses){pending=new State(d,yaw,pitch,zoom,background,poses);}
 static final class AntialiasConfig implements GLSurfaceView.EGLConfigChooser {
  public EGLConfig chooseConfig(EGL10 egl,EGLDisplay display){for(int samples:new int[]{4,2,0})for(int depth:new int[]{24,16}){int[] attributes={EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_DEPTH_SIZE,depth,EGL14.EGL_RENDERABLE_TYPE,EGL14.EGL_OPENGL_ES2_BIT,EGL14.EGL_SURFACE_TYPE,EGL14.EGL_WINDOW_BIT,EGL14.EGL_SAMPLE_BUFFERS,samples==0?0:1,EGL14.EGL_SAMPLES,samples,EGL14.EGL_NONE};int[] count=new int[1];if(egl.eglChooseConfig(display,attributes,null,0,count)&&count[0]>0){EGLConfig[] configs=new EGLConfig[count[0]];if(egl.eglChooseConfig(display,attributes,configs,configs.length,count))return configs[0];}}throw new IllegalArgumentException("Nenhuma configuração OpenGL ES compatível");}
 }
 private static int shader(int type,String source){int id=GLES20.glCreateShader(type);GLES20.glShaderSource(id,source);GLES20.glCompileShader(id);int[] ok=new int[1];GLES20.glGetShaderiv(id,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0){String log=GLES20.glGetShaderInfoLog(id);GLES20.glDeleteShader(id);throw new IllegalStateException("Shader: "+log);}return id;}
 private void error(State state,RuntimeException e){if(failed)return;failed=true;Log.e("PocketRobotGL","Renderização recusada",e);failure.accept(state.data,"OpenGL ES indisponível");}
 public void onSurfaceCreated(GL10 ignored,EGLConfig config){program=0;cadProgram=0;cadBuffers.clear();vbo=0;uploaded=null;failed=false;State state=pending;try{int vs=shader(GLES20.GL_VERTEX_SHADER,VERTEX),fs=shader(GLES20.GL_FRAGMENT_SHADER,FRAGMENT);program=GLES20.glCreateProgram();GLES20.glAttachShader(program,vs);GLES20.glAttachShader(program,fs);GLES20.glLinkProgram(program);GLES20.glDeleteShader(vs);GLES20.glDeleteShader(fs);int[] ok=new int[1];GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(program));position=GLES20.glGetAttribLocation(program,"aPosition");normal=GLES20.glGetAttribLocation(program,"aNormal");color=GLES20.glGetAttribLocation(program,"aColor");mvp=GLES20.glGetUniformLocation(program,"uMvp");viewDirection=GLES20.glGetUniformLocation(program,"uView");if(position<0||normal<0||color<0||mvp<0||viewDirection<0)throw new IllegalStateException("Atributo de shader ausente");GLES20.glEnable(GLES20.GL_DEPTH_TEST);GLES20.glDepthFunc(GLES20.GL_LEQUAL);GLES20.glDisable(GLES20.GL_CULL_FACE);GLES20.glEnable(GLES20.GL_BLEND);GLES20.glBlendFunc(GLES20.GL_SRC_ALPHA,GLES20.GL_ONE_MINUS_SRC_ALPHA);int[] samples=new int[1];GLES20.glGetIntegerv(GLES20.GL_SAMPLES,samples,0);Log.i("PocketRobotGL","renderer="+GLES20.glGetString(GLES20.GL_RENDERER)+" samples="+samples[0]);}catch(RuntimeException e){error(state,e);}}
 public void onSurfaceChanged(GL10 ignored,int w,int h){width=Math.max(1,w);height=Math.max(1,h);GLES20.glViewport(0,0,width,height);Log.i("PocketRobotGL","viewport="+width+"x"+height);}
 public void onDrawFrame(GL10 ignored){State s=pending;GLES20.glClearColor(Color.red(s.background)/255f,Color.green(s.background)/255f,Color.blue(s.background)/255f,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);if(failed||program==0)return;try{if(uploaded!=s.data){for(int[] ids:cadBuffers.values())GLES20.glDeleteBuffers(2,ids,0);cadBuffers.clear();if(vbo!=0){GLES20.glDeleteBuffers(1,new int[]{vbo},0);vbo=0;}uploaded=s.data;if(uploaded!=null&&uploaded.cad==null&&uploaded.triangleCount>0){int[] ids=new int[1];GLES20.glGenBuffers(1,ids,0);vbo=ids[0];GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,vbo);java.nio.FloatBuffer buffer=uploaded.vertices.duplicate();buffer.position(0);GLES20.glBufferData(GLES20.GL_ARRAY_BUFFER,buffer.remaining()*4,buffer,GLES20.GL_STATIC_DRAW);Log.i("PocketRobotGL","triangles="+uploaded.triangleCount+" vertexBytes="+(buffer.remaining()*4));}}if(s.data==null||s.data.triangleCount==0)return;if(s.data.cad!=null){drawCad(s);return;}GLES20.glUseProgram(program);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,vbo);GLES20.glEnableVertexAttribArray(position);GLES20.glEnableVertexAttribArray(normal);GLES20.glEnableVertexAttribArray(color);GLES20.glVertexAttribPointer(position,3,GLES20.GL_FLOAT,false,40,0);GLES20.glVertexAttribPointer(normal,3,GLES20.GL_FLOAT,false,40,12);GLES20.glVertexAttribPointer(color,4,GLES20.GL_FLOAT,false,40,24);GLES20.glUniformMatrix4fv(mvp,1,false,cameraMatrix(s.data,width,height,s.yaw,s.pitch,s.zoom),0);GLES20.glUniform3f(viewDirection,(float)(-Math.sin(s.yaw)*Math.cos(s.pitch)),(float)(-Math.cos(s.yaw)*Math.cos(s.pitch)),(float)Math.sin(s.pitch));GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,s.data.triangleCount*3);int code=GLES20.glGetError();if(code!=GLES20.GL_NO_ERROR)throw new IllegalStateException("GL error "+code);}catch(RuntimeException e){error(s,e);}}

 private static final String CAD_VERTEX="uniform mat4 uMvp; uniform mat3 uNormal; uniform vec4 uTint; attribute vec3 aPosition; attribute vec3 aNormal; attribute vec4 aColor; varying vec3 vNormal; varying vec4 vColor; void main(){gl_Position=uMvp*vec4(aPosition,1.0);vNormal=uNormal*aNormal;vColor=aColor*uTint;}";
 private void drawCad(State s){
  if(cadProgram==0){int vs=shader(GLES20.GL_VERTEX_SHADER,CAD_VERTEX),fs=shader(GLES20.GL_FRAGMENT_SHADER,FRAGMENT);cadProgram=GLES20.glCreateProgram();GLES20.glAttachShader(cadProgram,vs);GLES20.glAttachShader(cadProgram,fs);GLES20.glLinkProgram(cadProgram);GLES20.glDeleteShader(vs);GLES20.glDeleteShader(fs);int[] ok=new int[1];GLES20.glGetProgramiv(cadProgram,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException("CAD shader link failed");}
  GLES20.glUseProgram(cadProgram);int a=GLES20.glGetAttribLocation(cadProgram,"aPosition"),n=GLES20.glGetAttribLocation(cadProgram,"aNormal"),c=GLES20.glGetAttribLocation(cadProgram,"aColor");GLES20.glEnableVertexAttribArray(a);GLES20.glEnableVertexAttribArray(n);GLES20.glEnableVertexAttribArray(c);GLES20.glUniform3f(GLES20.glGetUniformLocation(cadProgram,"uView"),(float)(-Math.sin(s.yaw)*Math.cos(s.pitch)),(float)(-Math.cos(s.yaw)*Math.cos(s.pitch)),(float)Math.sin(s.pitch));
  float[] camera=cameraMatrix(s.data,width,height,s.yaw,s.pitch,s.zoom);int draws=0;
  for(RobotCad.Part part:s.data.cad.parts){double[] matrix=transform(part,s.poses);if(matrix==null)continue;float[] model=columnMatrix(matrix),inv=new float[16],normalMatrix=new float[9],mvp=new float[16];if(!android.opengl.Matrix.invertM(inv,0,model,0))throw new IllegalArgumentException("Escala CAD singular");for(int r=0;r<3;r++)for(int k=0;k<3;k++)normalMatrix[k*3+r]=inv[r*4+k];android.opengl.Matrix.multiplyMM(mvp,0,camera,0,model,0);GLES20.glUniformMatrix4fv(GLES20.glGetUniformLocation(cadProgram,"uMvp"),1,false,mvp,0);GLES20.glUniformMatrix3fv(GLES20.glGetUniformLocation(cadProgram,"uNormal"),1,false,normalMatrix,0);
   for(RobotCad.Chunk chunk:part.mesh.chunks){int[] ids=cadBuffers.get(chunk);if(ids==null){ids=new int[2];GLES20.glGenBuffers(2,ids,0);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,ids[0]);java.nio.FloatBuffer vs=chunk.vertices.duplicate();vs.position(0);GLES20.glBufferData(GLES20.GL_ARRAY_BUFFER,vs.remaining()*4,vs,GLES20.GL_STATIC_DRAW);GLES20.glBindBuffer(GLES20.GL_ELEMENT_ARRAY_BUFFER,ids[1]);java.nio.ShortBuffer ix=chunk.indices.duplicate();ix.position(0);GLES20.glBufferData(GLES20.GL_ELEMENT_ARRAY_BUFFER,ix.remaining()*2,ix,GLES20.GL_STATIC_DRAW);cadBuffers.put(chunk,ids);Log.i("PocketRobotGL","CAD upload vertices="+(vs.remaining()/10)+" indices="+ix.remaining());}GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,ids[0]);GLES20.glBindBuffer(GLES20.GL_ELEMENT_ARRAY_BUFFER,ids[1]);GLES20.glVertexAttribPointer(a,3,GLES20.GL_FLOAT,false,40,0);GLES20.glVertexAttribPointer(n,3,GLES20.GL_FLOAT,false,40,12);GLES20.glVertexAttribPointer(c,4,GLES20.GL_FLOAT,false,40,24);int color=!chunk.embedded&&part.visual.materialOverride?part.visual.color:0xffffffff;GLES20.glUniform4f(GLES20.glGetUniformLocation(cadProgram,"uTint"),Color.red(color)/255f,Color.green(color)/255f,Color.blue(color)/255f,Color.alpha(color)/255f);GLES20.glDrawElements(GLES20.GL_TRIANGLES,chunk.indices.limit(),GLES20.GL_UNSIGNED_SHORT,0);draws++;}
  }GLES20.glBindBuffer(GLES20.GL_ELEMENT_ARRAY_BUFFER,0);int code=GLES20.glGetError();if(code!=GLES20.GL_NO_ERROR)throw new IllegalStateException("CAD GL error "+code);
 }
 static double[] transform(RobotCad.Part part,java.util.Map<String,double[]> poses){if(poses==null)return part.model;double[] observed=poses.get(part.visual.link);return observed==null?null:RobotDescription.multiply(observed,part.local);}
 static float[] columnMatrix(double[] m){float[] out=new float[16];for(int r=0;r<4;r++)for(int c=0;c<4;c++){out[c*4+r]=(float)m[r*4+c];if(!Float.isFinite(out[c*4+r]))throw new IllegalArgumentException("Transformação CAD inválida");}return out;}
 static float[] cameraMatrix(RobotGpuMesh.Data data,int width,int height,double yaw,double pitch,float zoom){if(data==null||width<1||height<1||!Double.isFinite(yaw)||!Double.isFinite(pitch)||!Float.isFinite(zoom)||zoom<=0)throw new IllegalArgumentException("Câmera GPU inválida");float r=(float)data.radius,aspect=width/(float)height,half=r/(.9f*zoom)*Math.max(1,1/aspect);float[] projection=new float[16],view=new float[16],model=new float[16],mv=new float[16],mvp=new float[16];android.opengl.Matrix.orthoM(projection,0,-half*aspect,half*aspect,-half,half,r*.1f,r*10);android.opengl.Matrix.setLookAtM(view,0,(float)(-3*r*Math.sin(yaw)*Math.cos(pitch)),(float)(-3*r*Math.cos(yaw)*Math.cos(pitch)),(float)(3*r*Math.sin(pitch)),0,0,0,0,0,1);android.opengl.Matrix.setIdentityM(model,0);android.opengl.Matrix.translateM(model,0,(float)-data.cx,(float)-data.cy,(float)-data.cz);android.opengl.Matrix.multiplyMM(mv,0,view,0,model,0);android.opengl.Matrix.multiplyMM(mvp,0,projection,0,mv,0);return mvp;}
}
